use serde_json::Value;

pub fn solve(input: serde_json::Value) -> serde_json::Value {
    let shift = input["shift"].as_i64().expect("shift must be an integer");
    let text = input["text"].as_str().expect("text must be a string");

    let mut result = String::new();
    for c in text.chars() {
        if c.is_ascii_lowercase() {
            let rotated = ((c as u8 - b'a') + shift as u8) % 26 + b'a';
            result.push(rotated as char);
        } else {
            result.push(c);
        }
    }

    serde_json::Value::String(result)
}
